/// Return the representative shape character string of a single character (`ch` unchanged if outside Menk).
///
/// 获取单个字符对应的代表字形字符串（非孟克字符原样返回）。
pub fn get_char_shape(ch: char) -> String {
    if let Some(shapes) = menk_char_shapes(ch) {
        shapes.iter().map(|s| s.shape_char()).collect()
    } else {
        ch.to_string()
    }
}

/// Convert Menk characters in `text` to their representative shape characters, passing other characters through.
///
/// 将文本中的孟克字符转换为代表字形字符，其余字符原样保留。
pub fn get_shape(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    for ch in text.chars() {
        if let Some(shapes) = menk_char_shapes(ch) {
            for &s in shapes {
                out.push(s.shape_char());
            }
        } else {
            out.push(ch);
        }
    }
    out
}
